// Convert basic HTML paragraphs to readable plain text
return items.map(item => {
  const html = item.json.text;

  // Replace paragraph tags with newlines
  let text = html
    .replace(/<\/p>\s*/gi, '\n\n')  // Paragraph breaks
    .replace(/<[^>]+>/g, '')        // Remove all other HTML tags
    .replace(/&quot;/g, '"')        // Decode common entities
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>');

  return {
    json: {
      readable: text.trim()
    }
  };
});
